/* Pixel-style temperature converter — cohesive palette, accessible, responsive */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 3px solid var(--accent);
  box-shadow: 6px 6px 0 var(--accent);
  padding: 28px 24px;
  width: 100%;
  max-width: 400px;
  border-radius: 4px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--highlight);
  text-shadow: 2px 2px 0 var(--accent);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 20px;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 0.95rem;
  color: var(--text);
}

input, select {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--accent);
  border-radius: 2px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:focus, select:focus {
  border-color: var(--highlight);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input:hover, select:hover {
  border-color: var(--muted);
}

button {
  width: 100%;
  padding: 12px;
  font-size: 1.05rem;
  font-weight: 700;
  font-family: inherit;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  background: var(--highlight);
  border: 3px solid var(--accent);
  box-shadow: 4px 4px 0 var(--accent);
  border-radius: 2px;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, background 0.15s;
  margin-bottom: 20px;
}

button:hover {
  background: #ff5c7a;
}

button:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--accent);
}

.output {
  display: flex;
  align-items: baseline;
  gap: 10px;
  background: var(--bg);
  border: 2px dashed var(--accent);
  padding: 12px 16px;
  border-radius: 2px;
  margin-bottom: 20px;
}

.output-label {
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

#result {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--highlight);
  font-variant-numeric: tabular-nums;
  word-break: break-all;
}

.formulas {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.6;
  border-top: 2px solid var(--accent);
  padding-top: 12px;
}

.formulas p { margin: 0; }
.formulas strong { color: var(--text); }

[hidden] { display: none !important; }

@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.3rem; }
  #result { font-size: 1.3rem; }
}

(function () {
  'use strict';

  var input = document.getElementById('temperature');
  var direction = document.getElementById('direction');
  var button = document.getElementById('convert');
  var result = document.getElementById('result');

  function formatNumber(n) {
    return n.toFixed(2);
  }

  function convert() {
    var raw = input.value.trim();
    var num = Number(raw);

    if (raw === '' || !isFinite(num)) {
      result.textContent = 'Error';
      return;
    }

    var out;
    if (direction.value === 'c-to-f') {
      out = num * 9 / 5 + 32;
    } else {
      out = (num - 32) * 5 / 9;
    }

    if (!isFinite(out)) {
      result.textContent = 'Error';
      return;
    }

    result.textContent = formatNumber(out);
  }

  button.addEventListener('click', convert);

  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      convert();
    }
  });
})();
